    private int dp(float n){return design.dp(n);}
    private LinearLayout line(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    private TextView label(String s,float size,int color){return design.label(s,size,color);}
    private TextView button(String s,String icon,Runnable click){return design.button(s,icon,click);}
    private void addGap(LinearLayout l,int h){l.addView(new View(this),new LinearLayout.LayoutParams(1,dp(h)));}
    private void setText(TextView v,String s){if(!v.getText().toString().equals(s))v.setText(s);}
    private void remember(View v,String key,boolean first){v.setId(View.generateViewId());focusViews.put(key,v);if(first)v.setNextFocusLeftId(activeNav().getId());v.setOnFocusChangeListener((w,f)->{w.setBackground(design.surface(f,12));if(f){lastContent=key;w.post(images::visible);}});}
    private TextView activeNav(){return navigation.get("home".equals(tab)?0:"search".equals(tab)?1:"favorites".equals(tab)?2:"queue".equals(tab)?3:4);}
    private boolean restoreFocus(String key){View v=focusViews.get(key);return v!=null&&v.isShown()&&v.requestFocus();}
    private void focusContent(){if(!restoreFocus(lastContent)){for(View v:focusViews.values())if(v.isShown()&&v.isFocusable()){v.requestFocus();return;}sourceButton.requestFocus();}}
    private void select(String page){if(query!=null)queryText=query.getText().toString();if(!"settings".equals(tab))returnTab=tab;tab=page;render();focusContent();}
    private ScrollView scroll(LinearLayout child){ScrollView s=new ScrollView(this);s.setFillViewport(true);s.setClipToPadding(false);s.addView(child);s.setOnScrollChangeListener((v,x,y,ox,oy)->images.visible());content.addView(s,new FrameLayout.LayoutParams(-1,-1));return s;}
    private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private TextView section(LinearLayout parent,String text){TextView t=label(text,15,design.skin.text);t.setPadding(0,dp(6),0,dp(7));parent.addView(t,new LinearLayout.LayoutParams(-1,dp(30)));return t;}

    private void buildBar(){
        bar=line();bar.setPadding(dp(14),dp(10),dp(14),dp(10));bar.setBackground(design.surface(false,16));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(80));p.topMargin=dp(12);shell.addView(bar,p);
        barArt=new LauncherinMusicDesign.Image(this,false);barArt.setScaleType(ImageView.ScaleType.CENTER_CROP);barArt.setBackground(design.surface(false,8));barArt.setClipToOutline(true);bar.addView(barArt,new LinearLayout.LayoutParams(dp(48),dp(48)));
        LinearLayout info=column();info.setPadding(dp(10),0,dp(8),0);barTitle=label("Escolha uma música",14,design.skin.text);barTitle.setMaxLines(2);barTitle.setEllipsize(TextUtils.TruncateAt.END);barArtist=label("Sua biblioteca está pronta",12,design.skin.muted);barArtist.setSingleLine(true);barArtist.setEllipsize(TextUtils.TruncateAt.END);info.addView(barTitle);info.addView(barArtist);bar.addView(info,new LinearLayout.LayoutParams(dp(155),-2));
        TextView previous=design.icon("previous","Faixa anterior",21,()->command("previous"));bar.addView(previous,new LinearLayout.LayoutParams(dp(37),dp(39)));
        play=design.icon("play","Reproduzir",22,()->command("toggle"));LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(dp(48),dp(48));pp.leftMargin=dp(6);pp.rightMargin=dp(6);bar.addView(play,pp);
        TextView next=design.icon("next","Próxima faixa",21,()->command("next"));bar.addView(next,new LinearLayout.LayoutParams(dp(37),dp(39)));
        LinearLayout timeline=column();timeline.setPadding(dp(12),0,dp(12),0);seek=new SeekBar(this);seek.setMax(1000);seek.setContentDescription("Posição da música");seek.setFocusable(true);seek.setProgressTintList(android.content.res.ColorStateList.valueOf(design.skin.accent));timeline.addView(seek,new LinearLayout.LayoutParams(-1,dp(23)));LinearLayout times=line();elapsed=label("0:00",10,design.skin.muted);total=label("0:00",10,design.skin.muted);total.setGravity(Gravity.RIGHT);times.addView(elapsed,new LinearLayout.LayoutParams(0,-2,1));times.addView(total,new LinearLayout.LayoutParams(0,-2,1));timeline.addView(times);bar.addView(timeline,new LinearLayout.LayoutParams(0,-2,1));
        seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean user){if(user){JSONObject snap=LauncherinPlayerService.snapshot(LauncherinPlayerActivity.this);LauncherinPlayerService.seek(LauncherinPlayerActivity.this,snap.optLong("duration")*p/1000);}}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});
        TextView words=button("Letra","lyrics",this::openLyrics);TextView protect=button("Protetor","saver",()->startSaver(false));bar.addView(words,new LinearLayout.LayoutParams(dp(86),dp(42)));LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(dp(105),dp(42));sp.leftMargin=dp(7);bar.addView(protect,sp);
        play.setOnKeyListener((v,key,e)->{if(e.getAction()!=KeyEvent.ACTION_DOWN)return false;if(key==KeyEvent.KEYCODE_DPAD_UP){focusContent();return true;}return key==KeyEvent.KEYCODE_DPAD_DOWN;});
        for(TextView b:new TextView[]{previous,play,next})b.setOnLongClickListener(v->{select("queue");return true;});
    }
    private void render(){
        if(closed)return;String focused=lastContent;content.removeAllViews();focusViews.clear();images.clear();artKey="";query=null;status=null;
        setText(sourceButton,"soundcloud".equals(sourceName)?"SoundCloud ▾":"YouTube ▾");sourceButton.setVisibility("settings".equals(tab)?View.GONE:View.VISIBLE);
        for(int i=0;i<navigation.size();i++){TextView b=navigation.get(i);if(b==activeNav()||b.hasFocus())b.setBackground(design.surface(b.hasFocus(),12));else b.setBackgroundColor(Color.TRANSPARENT);}
        if("home".equals(tab)){heading.setText("Sua biblioteca");home();}
        else if("search".equals(tab)){heading.setText(artistQuery.isEmpty()?"Buscar músicas":artistQuery);searchPage();}
        else if("favorites".equals(tab)){heading.setText("Favoritos");favorites();}
        else if("queue".equals(tab)){heading.setText("Fila de reprodução");listPage(LauncherinPlayerService.tracks(this),true);}
        else{heading.setText("Proteção e preferências");settings();}
        refresh();content.post(images::visible);
        if(!focused.isEmpty()&&focusViews.containsKey(focused))restoreFocus(focused);
    }
    private void home(){
        LinearLayout col=column();scroll(col);section(col,"Artistas e bandas favoritos");artistStrip(col,library.artists(),false);section(col,"Músicas favoritas");
        List<LauncherinTrack> favorites=library.read("favorites");if(favorites.isEmpty()){TextView empty=button("Adicionar música favorita","add",()->{artistQuery="";select("search");});remember(empty,"add-song",true);col.addView(empty,new LinearLayout.LayoutParams(dp(210),dp(100)));}
        else musicStrip(col,favorites);
    }
    private void favorites(){
        LinearLayout col=column();scroll(col);LinearLayout filters=line();TextView songs=button("Músicas","heart",()->{favoriteKind="songs";render();focusContent();}),artists=button("Artistas e bandas",null,()->{favoriteKind="artists";render();focusContent();});filters.addView(songs,new LinearLayout.LayoutParams(dp(130),dp(36)));LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(dp(190),dp(36));ap.leftMargin=dp(8);filters.addView(artists,ap);remember(songs,"filter-songs",true);remember(artists,"filter-artists",false);col.addView(filters);addGap(col,12);
        if("artists".equals(favoriteKind)){section(col,"Seus artistas");artistStrip(col,library.artists(),true);}
        else{section(col,"Suas músicas");List<LauncherinTrack> list=library.read("favorites");if(list.isEmpty())empty(col,"Nenhuma música favorita ainda.","Buscar músicas",()->{artistQuery="";select("search");});else musicGrid(col,list,false);}
    }
    private void artistStrip(LinearLayout parent,List<LauncherinMusicLibrary.Artist> artists,boolean full){
        HorizontalScrollView s=new HorizontalScrollView(this);s.setHorizontalScrollBarEnabled(false);s.setClipToPadding(false);s.setOnScrollChangeListener((v,x,y,ox,oy)->images.visible());LinearLayout row=line();s.addView(row);parent.addView(s,new LinearLayout.LayoutParams(-1,dp(122)));
        int limit=full?artists.size():Math.min(8,artists.size());for(int i=0;i<limit;i++){LauncherinMusicLibrary.Artist a=artists.get(i);LinearLayout tile=column();tile.setPadding(dp(7),dp(3),dp(7),dp(3));tile.setGravity(Gravity.CENTER);ImageView avatar=new LauncherinMusicDesign.Image(this,true);avatar.setScaleType(ImageView.ScaleType.CENTER_CROP);GradientDrawable shape=new GradientDrawable();shape.setColor(Color.TRANSPARENT);shape.setShape(GradientDrawable.OVAL);avatar.setBackground(shape);avatar.setClipToOutline(true);tile.addView(avatar,new LinearLayout.LayoutParams(dp(76),dp(76)));TextView name=label(a.name,13,design.skin.text);name.setGravity(Gravity.CENTER);name.setSingleLine(true);name.setEllipsize(TextUtils.TruncateAt.END);LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(-1,dp(26));np.topMargin=dp(6);tile.addView(name,np);tile.setFocusable(true);tile.setClickable(true);tile.setContentDescription(a.name+", abrir músicas e opções");tile.setOnClickListener(v->browseArtist(a));tile.setOnLongClickListener(v->{artistActions(a);return true;});remember(tile,"artist:"+a.key(),i==0);tile.setOnFocusChangeListener((v,f)->{tile.setBackgroundColor(Color.TRANSPARENT);GradientDrawable ring=new GradientDrawable();ring.setShape(GradientDrawable.OVAL);ring.setColor(Color.TRANSPARENT);ring.setStroke(dp(f?2:0),design.skin.accent);avatar.setForeground(ring);name.setTextColor(f?design.skin.accent:design.skin.text);if(f){lastContent="artist:"+a.key();tile.post(images::visible);}});LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(dp(116),dp(118));tp.rightMargin=dp(8);row.addView(tile,tp);images.bind(avatar,a.art,160,160,design.placeholder(a.name,true));}
        TextView add=button("+\nAdicionar artista",null,()->editArtist(null));add.setGravity(Gravity.CENTER);add.setTextSize(15);remember(add,"add-artist",artists.isEmpty());row.addView(add,new LinearLayout.LayoutParams(dp(116),dp(110)));
    }
    private void browseArtist(LauncherinMusicLibrary.Artist a){currentArtist=a;sourceName=a.source;library.source(sourceName);artistQuery=a.name;queryText=a.name;results.clear();tab="search";render();search();}
    private void artistActions(LauncherinMusicLibrary.Artist a){show(new AlertDialog.Builder(this).setTitle(a.name).setItems(new String[]{"Ouvir músicas deste artista","Editar nome e fonte","Remover dos favoritos"},(d,n)->{if(n==0){browseArtist(a);}else if(n==1)editArtist(a);else{library.removeArtist(a);if(currentArtist!=null&&currentArtist.key().equals(a.key()))currentArtist=null;render();focusContent();}}).setNegativeButton("Voltar",null).create());}
    private void editArtist(LauncherinMusicLibrary.Artist original){
        LauncherinTrack t=track();EditText name=new EditText(this);name.setSingleLine(true);name.setText(original!=null?original.name:t==null?"":t.artist.replaceFirst("(?i)\\s*-\\s*topic$",""));name.setHint("Nome do artista ou banda");name.setFilters(new InputFilter[]{new InputFilter.LengthFilter(120)});
        LinearLayout fields=column();fields.setPadding(dp(20),0,dp(20),0);fields.addView(name);TextView provider=button("Fonte: "+(original==null?sourceLabel():labelSource(original.source)),null,()->{});final String[] chosen={original==null?sourceName:original.source};provider.setOnClickListener(v->{chosen[0]="soundcloud".equals(chosen[0])?"youtube":"soundcloud";provider.setText("Fonte: "+labelSource(chosen[0]));});fields.addView(provider,new LinearLayout.LayoutParams(-1,dp(42)));
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle(original==null?"Artista ou banda favorita":"Editar artista").setView(fields).setPositiveButton("Salvar",null).setNegativeButton("Cancelar",null).create();
        dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String value=name.getText().toString().trim();if(value.isEmpty()){name.setError("Informe o nome.");return;}String art=original!=null?original.art:t!=null&&value.equals(t.artist)?t.artistArt:"";try{LauncherinMusicLibrary.Artist a=new LauncherinMusicLibrary.Artist(value,chosen[0],art);if(original!=null)library.removeArtist(original);library.saveArtist(a);if(currentArtist!=null&&original!=null&&currentArtist.key().equals(original.key())){currentArtist=a;artistQuery=a.name;}dialog.dismiss();render();focusContent();}catch(IllegalArgumentException e){name.setError(e.getMessage());}}));show(dialog);
    }
    private void musicStrip(LinearLayout parent,List<LauncherinTrack> list){HorizontalScrollView s=new HorizontalScrollView(this);s.setHorizontalScrollBarEnabled(false);s.setClipToPadding(false);s.setOnScrollChangeListener((v,x,y,ox,oy)->images.visible());LinearLayout row=line();s.addView(row);parent.addView(s,new LinearLayout.LayoutParams(-1,dp(151)));for(int i=0;i<Math.min(16,list.size());i++){LinearLayout tile=musicCard(list,i,false);tile.setNextFocusLeftId(i==0?activeNav().getId():View.NO_ID);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(158),dp(146));p.rightMargin=dp(10);row.addView(tile,p);}TextView add=button("+\nAdicionar música",null,()->{artistQuery="";select("search");});add.setGravity(Gravity.CENTER);remember(add,"add-song",list.isEmpty());row.addView(add,new LinearLayout.LayoutParams(dp(142),dp(142)));}
    private LinearLayout musicCard(List<LauncherinTrack> list,int at,boolean queue){LauncherinTrack t=list.get(at);LinearLayout tile=column();tile.setPadding(dp(4),dp(4),dp(4),dp(5));ImageView image=new LauncherinMusicDesign.Image(this,false);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setBackground(design.surface(false,9));image.setClipToOutline(true);tile.addView(image,new LinearLayout.LayoutParams(-1,0,1));TextView name=label(t.title,13,design.skin.text);name.setSingleLine(true);name.setEllipsize(TextUtils.TruncateAt.END);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(22));p.topMargin=dp(5);tile.addView(name,p);TextView artist=label(t.artist,11,design.skin.muted);artist.setSingleLine(true);artist.setEllipsize(TextUtils.TruncateAt.END);tile.addView(artist);tile.setFocusable(true);tile.setClickable(true);tile.setContentDescription(t.title+", "+t.artist+", abrir ações da música");tile.setOnClickListener(v->musicActions(list,at,queue));tile.setOnLongClickListener(v->{musicActions(list,at,queue);return true;});remember(tile,"track:"+t.url,at%3==0);tile.setNextFocusDownId(play.getId());images.bind(image,t.art,320,240,design.placeholder(t.title,false));return tile;}
    private void musicGrid(LinearLayout parent,List<LauncherinTrack> list,boolean queue){shown=new ArrayList<>(list);GridLayout grid=new GridLayout(this);grid.setColumnCount(3);parent.addView(grid,new LinearLayout.LayoutParams(-1,-2));for(int i=0;i<list.size();i++){LinearLayout tile=musicCard(list,i,queue);tile.setNextFocusDownId(i+3<list.size()?View.NO_ID:play.getId());GridLayout.LayoutParams p=new GridLayout.LayoutParams(GridLayout.spec(i/3),GridLayout.spec(i%3,1f));p.width=0;p.height=dp(149);p.rightMargin=dp(9);p.bottomMargin=dp(12);grid.addView(tile,p);}}
    private void listPage(List<LauncherinTrack> tracks,boolean queue){LinearLayout col=column();scroll(col);if(tracks.isEmpty()){empty(col,"Sua fila está vazia.","Buscar músicas",()->{artistQuery="";select("search");});return;}status=label(tracks.size()+" músicas · OK abre as ações",12,design.skin.muted);status.setPadding(0,dp(5),0,dp(9));col.addView(status);for(int i=0;i<tracks.size();i++){LauncherinTrack t=tracks.get(i);int at=i;LinearLayout row=line();row.setPadding(dp(8),dp(6),dp(10),dp(6));row.setFocusable(true);row.setClickable(true);ImageView art=new ImageView(this);art.setScaleType(ImageView.ScaleType.CENTER_CROP);row.addView(art,new LinearLayout.LayoutParams(dp(44),dp(44)));LinearLayout labels=column();labels.setPadding(dp(13),0,0,0);TextView name=label((i+1)+"  "+t.title,15,design.skin.text);name.setSingleLine(true);name.setEllipsize(TextUtils.TruncateAt.END);TextView sub=label(t.artist+" · "+time(t.duration),12,design.skin.muted);sub.setSingleLine(true);sub.setEllipsize(TextUtils.TruncateAt.END);labels.addView(name);labels.addView(sub);row.addView(labels,new LinearLayout.LayoutParams(0,-2,1));TextView options=label("⋯",24,design.skin.muted);row.addView(options);row.setOnClickListener(v->musicActions(tracks,at,queue));remember(row,"track:"+t.url,true);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(62));p.bottomMargin=dp(6);col.addView(row,p);images.bind(art,t.art,128,128,design.placeholder(t.title,false));}}
    private void musicActions(List<LauncherinTrack> list,int at,boolean queue){LauncherinTrack t=list.get(at);String[] options=queue?new String[]{"Tocar a partir desta música","Adicionar novamente à fila",library.favorite(t)?"Remover música dos favoritos":"Favoritar música","Favoritar artista ou banda","Remover da fila"}:new String[]{"Tocar agora","Adicionar à fila",library.favorite(t)?"Remover música dos favoritos":"Favoritar música","Favoritar artista ou banda"};show(new AlertDialog.Builder(this).setTitle(t.title).setItems(options,(d,n)->{if(n==0){LauncherinPlayerService.play(this,new ArrayList<>(list),at);refresh();}else if(n==1){LauncherinPlayerService.enqueue(this,t);toast("Adicionada à fila");}else if(n==2){library.toggle(t);if("home".equals(tab)||"favorites".equals(tab))render();}else if(n==3){editArtist(new LauncherinMusicLibrary.Artist(t.artist.isEmpty()?"Artista":t.artist,"SoundCloud".equals(t.source)?"soundcloud":"youtube",t.artistArt));}else{if(t.url.equals(LauncherinPlayerService.snapshot(this).optString("url"))){toast("Escolha outra faixa antes de remover a atual.");return;}LauncherinPlayerService.remove(this,at);render();}}).setNegativeButton("Voltar",null).create());}

    private void searchPage(){LinearLayout col=column();content.addView(col,new FrameLayout.LayoutParams(-1,-1));LinearLayout line=line();query=new EditText(this);query.setId(View.generateViewId());query.setTextColor(design.skin.text);query.setTextSize(16);query.setHintTextColor(design.skin.muted);query.setHint("Música, artista ou banda");query.setSingleLine(true);query.setPadding(dp(12),0,dp(12),0);query.setBackground(design.surface(false,12));query.setFilters(new InputFilter[]{new InputFilter.LengthFilter(160)});query.setImeOptions(EditorInfo.IME_ACTION_SEARCH);query.setText(queryText);line.addView(query,new LinearLayout.LayoutParams(0,dp(42),1));focusViews.put("search-input",query);query.setNextFocusLeftId(activeNav().getId());query.setOnFocusChangeListener((v,f)->{if(f)lastContent="search-input";});TextView find=button("Buscar","search",this::search);remember(find,"search-submit",false);LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(dp(118),dp(42));fp.leftMargin=dp(9);line.addView(find,fp);col.addView(line);if(currentArtist!=null){TextView manage=button("Artista favorito · opções","heart",()->artistActions(currentArtist));remember(manage,"artist-options",true);LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(-1,dp(34));mp.topMargin=dp(6);col.addView(manage,mp);}query.setNextFocusRightId(find.getId());find.setNextFocusLeftId(query.getId());query.setOnEditorActionListener((v,action,event)->{if(action==EditorInfo.IME_ACTION_SEARCH||event!=null&&event.getAction()==KeyEvent.ACTION_DOWN){search();return true;}return false;});
        status=label(busy?"Buscando músicas…":results.isEmpty()?"Digite e selecione Buscar.":"Resultados · "+sourceLabel(),12,design.skin.muted);status.setPadding(0,dp(9),0,dp(9));col.addView(status);FrameLayout holder=new FrameLayout(this);col.addView(holder,new LinearLayout.LayoutParams(-1,0,1));ScrollView s=new ScrollView(this);s.setOnScrollChangeListener((v,x,y,ox,oy)->images.visible());LinearLayout songs=column();s.addView(songs);holder.addView(s,new FrameLayout.LayoutParams(-1,-1));if(!results.isEmpty())musicGrid(songs,results,false);
    }
    private void search(){if(query!=null)queryText=query.getText().toString().trim();if(queryText.isEmpty()){if(query!=null)query.requestFocus();return;}if(queryText.length()>160){toast("Use até 160 caracteres.");return;}if(!"search".equals(tab)){tab="search";render();}final int request=++searchGeneration;final String text=queryText;final boolean sc="soundcloud".equals(sourceName);busy=true;if(status!=null)status.setText("Buscando músicas…");if(searchJob!=null)searchJob.cancel(true);searchWorker.getQueue().clear();if(query!=null)getSystemService(InputMethodManager.class).hideSoftInputFromWindow(query.getWindowToken(),0);
        searchJob=searchWorker.submit(()->{try{List<LauncherinTrack> found=searchSource.search(text,sc);main.post(()->{if(closed||!active||request!=searchGeneration)return;busy=false;results=found;lastInteraction=SystemClock.elapsedRealtime();if("search".equals(tab)){lastContent="";render();if(status!=null)status.setText(found.isEmpty()?"Nenhuma música encontrada. Tente outra busca.":"Resultados · "+sourceLabel());if(!found.isEmpty())restoreFocus("track:"+found.get(0).url);}});}catch(Exception e){main.post(()->{if(!closed&&active&&request==searchGeneration){busy=false;if(status!=null)status.setText(LauncherinMusicSource.error(e));}});}});
    }
    private String sourceLabel(){return labelSource(sourceName);}
    private String labelSource(String s){return "soundcloud".equals(s)?"SoundCloud":"YouTube";}
    private void chooseSource(){show(new AlertDialog.Builder(this).setTitle("Fonte das músicas").setSingleChoiceItems(new String[]{"YouTube","SoundCloud"},"soundcloud".equals(sourceName)?1:0,(d,n)->{sourceName=n==1?"soundcloud":"youtube";library.source(sourceName);results.clear();++searchGeneration;if(searchJob!=null)searchJob.cancel(true);busy=false;d.dismiss();render();if("search".equals(tab)&&!queryText.isEmpty())search();}).setNegativeButton("Cancelar",null).create());}
    private void empty(LinearLayout col,String message,String action,Runnable click){TextView text=label(message,17,design.skin.muted);text.setPadding(dp(8),dp(24),dp(8),dp(18));col.addView(text);TextView b=button(action,"add",click);remember(b,"empty-action",true);col.addView(b,new LinearLayout.LayoutParams(dp(210),dp(44)));}

    private void settings(){
        LinearLayout col=column();scroll(col);section(col,"Protetor durante o áudio");
        String[] ids={"cover","photos","dark","google"},titles={"Capa flutuante","Fotos em sequência","Modo escuro","Google Fotos"},notes={"Capa e informações mudam de posição.","Fotos enviadas ao Porta-retratos; informações em movimento.","Fundo preto e informações discretas em movimento.","Usa o álbum e o temporizador do modo ambiente da TV."};
        GridLayout modes=new GridLayout(this);modes.setColumnCount(2);col.addView(modes,new LinearLayout.LayoutParams(-1,-2));for(int i=0;i<ids.length;i++){String mode=ids[i];LinearLayout row=column();row.setPadding(dp(13),dp(8),dp(13),dp(8));row.setFocusable(true);row.setClickable(true);TextView name=label((mode.equals(library.saverMode())?"●  ":"○  ")+titles[i],16,design.skin.text);TextView note=label(notes[i],12,design.skin.muted);note.setMaxLines(2);note.setEllipsize(TextUtils.TruncateAt.END);row.addView(name);row.addView(note);row.setOnClickListener(v->{library.saverMode(mode);lastContent="saver-mode:"+mode;render();});remember(row,"saver-mode:"+mode,i%2==0);row.setBackground(design.surface(mode.equals(library.saverMode()),12));GridLayout.LayoutParams p=new GridLayout.LayoutParams(GridLayout.spec(i/2),GridLayout.spec(i%2));p.width=Math.max(dp(120),((content.getWidth()>0?content.getWidth():getResources().getDisplayMetrics().widthPixels-dp(208))-dp(16))/2);p.height=dp(82);p.rightMargin=dp(8);p.bottomMargin=dp(8);modes.addView(row,p);}
        boolean google="google".equals(library.saverMode());TextView delay=button(google?"Tempo: definido no modo ambiente da TV":"Iniciar na tela de música: "+delayLabel(library.saverSeconds()),null,()->{if(google)googleInfo();else chooseDelay();});remember(delay,"saver-time",true);col.addView(delay,new LinearLayout.LayoutParams(-1,dp(43)));addGap(col,8);
        TextView preview=button(google?"Configurar álbum do Google Fotos":"Visualizar protetor",google?"settings":"saver",()->{if(google)openGoogleSettings();else startSaver(false);});remember(preview,"saver-preview",true);col.addView(preview,new LinearLayout.LayoutParams(-1,dp(43)));addGap(col,12);
        TextView info=label("Os modos próprios atuam nesta tela. Ao voltar à Home, vale o protetor configurado na TV. A música continua e a regra de desligamento é preservada.",12,design.skin.muted);col.addView(info);addGap(col,18);
        TextView external=button("Usar controles de aplicativos externos",null,()->{LauncherinPlayerService.external(this);finish();});remember(external,"external",true);col.addView(external,new LinearLayout.LayoutParams(-1,dp(43)));TextView about=button("Sobre e licenças",null,this::about);remember(about,"about",true);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,dp(43));ap.topMargin=dp(8);col.addView(about,ap);
    }
    private String delayLabel(int seconds){return seconds==0?"Somente manual":seconds<60?seconds+" segundos":seconds/60+" minuto"+(seconds==60?"":"s");}
    private void chooseDelay(){int[] values={30,60,120,300,0};String[] labels=new String[values.length];int selected=1;for(int i=0;i<values.length;i++){labels[i]=delayLabel(values[i]);if(values[i]==library.saverSeconds())selected=i;}show(new AlertDialog.Builder(this).setTitle("Inatividade na tela de música").setSingleChoiceItems(labels,selected,(d,n)->{library.saverSeconds(values[n]);d.dismiss();render();}).setNegativeButton("Cancelar",null).create());}
    private void googleInfo(){show(new AlertDialog.Builder(this).setTitle("Google Fotos no protetor de áudio").setMessage("A música continua no player da Launcherin enquanto a TV mostra o álbum selecionado no seu modo ambiente.\n\nNa TCL com Android 14, a entrada acontece pelo tempo de inatividade configurado na própria TV. Escolha Google Fotos e o álbum nas configurações abaixo. A Launcherin não recebe sua senha nem baixa seu álbum privado.").setPositiveButton("Abrir modo ambiente",(d,n)->openGoogleSettings()).setNegativeButton("Voltar",null).create());}
    private void openGoogleSettings(){try{startActivity(new Intent(android.provider.Settings.ACTION_DREAM_SETTINGS));}catch(RuntimeException e){toast("Abra Configurações → Sistema → Modo ambiente na TV.");}}
    private void startSaver(boolean automatic){if(saver!=null)return;if("google".equals(library.saverMode())){if(!automatic)googleInfo();return;}LauncherinTrack t=track();if(t==null){if(!automatic)toast("Escolha uma música para visualizar o protetor.");return;}closeLyrics();saver=new LauncherinAudioSaverView(this,library.saverMode(),images);shell.setVisibility(View.GONE);root.addView(saver,new FrameLayout.LayoutParams(-1,-1));saver.requestFocus();saver.update(t,SystemClock.elapsedRealtime());}
    private void stopSaver(){if(saver==null)return;saver.release();root.removeView(saver);saver=null;shell.setVisibility(View.VISIBLE);lastInteraction=SystemClock.elapsedRealtime();root.setKeepScreenOn(false);play.requestFocus();images.visible();}
    private void openLyrics(){LauncherinTrack t=track();if(t==null){toast("Escolha uma música para ver a letra.");return;}stopSaver();lyricsVisible=true;overlay.removeAllViews();overlay.setBackground(design.backdrop());overlay.setVisibility(View.VISIBLE);LinearLayout pane=column();pane.setPadding(dp(42),dp(24),dp(42),dp(24));overlay.addView(pane,new FrameLayout.LayoutParams(-1,-1));LinearLayout header=line();TextView back=button("Biblioteca","back",this::closeLyrics);header.addView(back,new LinearLayout.LayoutParams(dp(155),dp(42)));TextView song=label(t.title+" · "+t.artist,18,design.skin.text);song.setSingleLine(true);song.setEllipsize(TextUtils.TruncateAt.END);song.setPadding(dp(20),0,0,0);header.addView(song,new LinearLayout.LayoutParams(0,-2,1));pane.addView(header);
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setFocusable(true);lyricsText=label("Buscando letra…",26,design.skin.text);lyricsText.setGravity(Gravity.CENTER);lyricsText.setPadding(dp(50),dp(35),dp(50),dp(35));scroll.addView(lyricsText);pane.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));back.requestFocus();loadLyrics(t);
    }
    private void loadLyrics(LauncherinTrack t){if(t.url.equals(lyricsKey)&&lyrics!=null){lyricsLine=-2;renderLyrics(LauncherinPlayerService.snapshot(this).optLong("position"));return;}lyricsKey=t.url;lyrics=null;lyricsLine=-2;int request=++lyricsGeneration;if(lyricJob!=null)lyricJob.cancel(true);lyricJob=lyricWorker.submit(()->{LauncherinLyrics.Result result=null;try{result=LauncherinLyrics.load(this,t);}catch(Exception ignored){}final LauncherinLyrics.Result ready=result;main.post(()->{if(closed||!active||request!=lyricsGeneration||!lyricsVisible)return;lyrics=ready==null?new LauncherinLyrics.Result("","",false):ready;renderLyrics(LauncherinPlayerService.snapshot(this).optLong("position"));});});}
    private void renderLyrics(long position){if(!lyricsVisible||lyricsText==null||lyrics==null)return;if(lyrics.lines.isEmpty()){String value=lyrics.instrumental?"Faixa instrumental":lyrics.plain.isEmpty()?"Letra não encontrada para esta gravação.":lyrics.plain;setText(lyricsText,value);return;}int at=lyrics.at(position);if(at==lyricsLine)return;lyricsLine=at;SpannableStringBuilder text=new SpannableStringBuilder();int first=Math.max(0,at-2),end=Math.min(lyrics.lines.size(),Math.max(5,at+3));for(int i=first;i<end;i++){int start=text.length();text.append(lyrics.lines.get(i).text).append("\n\n");text.setSpan(new ForegroundColorSpan(i==at?design.skin.accent:0xff83938e),start,text.length(),Spannable.SPAN_EXCLUSIVE_EXCLUSIVE);if(i==at)text.setSpan(new StyleSpan(Typeface.BOLD),start,text.length(),Spannable.SPAN_EXCLUSIVE_EXCLUSIVE);}lyricsText.setText(text);}
    private void closeLyrics(){if(!lyricsVisible)return;lyricsVisible=false;overlay.setVisibility(View.GONE);overlay.removeAllViews();lastInteraction=SystemClock.elapsedRealtime();if(play!=null)play.requestFocus();}
    private void about(){show(new AlertDialog.Builder(this).setTitle("Música da Launcherin").setMessage("Player próprio com NewPipe Extractor v0.27.1, sob GPL-3.0-ou-posterior. Letras opcionais: LRCLIB. A variante combinada da TV é GPL-3.0-ou-posterior; os avisos MIT da base são preservados.\n\nRhino (MPL-2.0), jsoup (MIT), nanojson e JSR-305 (Apache-2.0), Protocol Buffers (BSD) e bibliotecas Android/AndroidX/desugaring com suas licenças originais.\n\nCódigo e textos: github.com/allanlribeiro/laucherin · assets/licenses.").setPositiveButton("Licença GPL",(d,n)->{try(java.io.InputStream in=getAssets().open("licenses/GPL-3.0.txt")){TextView text=label(new String(LauncherinExtras.bytes(in,60000),java.nio.charset.StandardCharsets.UTF_8),12,design.skin.text);text.setPadding(dp(18),dp(15),dp(18),dp(15));ScrollView scroll=new ScrollView(this);scroll.addView(text);show(new AlertDialog.Builder(this).setTitle("GPL-3.0-ou-posterior").setView(scroll).setPositiveButton("Fechar",null).create());}catch(Exception ignored){}}).setNeutralButton("Diagnóstico externo",(d,n)->LauncherinMusicActions.diagnostic(this)).setNegativeButton("Fechar",null).create());}

    private void refresh(){
        if(closed||library==null)return;JSONObject snap=LauncherinPlayerService.snapshot(this);LauncherinTrack t=LauncherinTrack.read(snap);boolean playing=snap.optBoolean("playing"),buffering=snap.optBoolean("buffering");String control=buffering?"Cancelar carregamento":playing?"Pausar":"Reproduzir";if(!control.equals(play.getContentDescription())){play.setContentDescription(control);play.setForeground(new LauncherinMusicDesign.Icon(playing?"pause":"play",design.skin.text,dp(22)));}
        setText(barTitle,t==null?"Escolha uma música":t.title);setText(barArtist,t==null?"Abra Buscar para começar":buffering?"Carregando áudio…":!snap.optString("error").isEmpty()?snap.optString("error"):t.artist);
        if(t!=null){String key=t.url+"|"+t.art;if(!key.equals(artKey)){artKey=key;images.bind(barArt,t.art,128,128,design.placeholder(t.title,false));}long pos=snap.optLong("position");seek.setProgress(t.duration>0?(int)Math.min(1000,Math.max(0,pos)*1000/t.duration):0);setText(elapsed,time(pos));setText(total,time(t.duration));if(!t.url.equals(lastTrack)){lastTrack=t.url;lyricsKey="";if(lyricsVisible)openLyrics();}if(lyricsVisible){if(!t.url.equals(lyricsKey))loadLyrics(t);renderLyrics(pos);}if(saver!=null)saver.update(t,SystemClock.elapsedRealtime());}
        else if(artKey.isEmpty())barArt.setImageDrawable(design.placeholder("",false));
        boolean local=!"google".equals(library.saverMode())&&library.saverSeconds()>0;root.setKeepScreenOn(active&&playing&&(saver!=null||local&&!lyricsVisible&&!dialogOpen&&!busy&&!"settings".equals(tab)));
        if(active&&saver==null&&!lyricsVisible&&!"settings".equals(tab)&&LauncherinAudioSaverPolicy.start(library.saverMode(),library.saverSeconds(),playing,busy||dialogOpen||!hasWindowFocus(),lastInteraction,SystemClock.elapsedRealtime()))startSaver(true);
        images.visible();
    }
    private LauncherinTrack track(){return LauncherinTrack.read(LauncherinPlayerService.snapshot(this));}
    private void command(String action){if(LauncherinPlayerService.tracks(this).isEmpty()){artistQuery="";select("search");toast("Escolha uma música para começar.");return;}LauncherinPlayerService.command(this,action);}
    private void toast(String message){Toast.makeText(this,message,Toast.LENGTH_SHORT).show();}
    private void show(AlertDialog dialog){dialogOpen=true;dialog.setOnDismissListener(d->{dialogOpen=false;lastInteraction=SystemClock.elapsedRealtime();});dialog.show();}
    static String time(long ms){long seconds=Math.max(0,ms)/1000;return seconds/60+":"+String.format(Locale.ROOT,"%02d",seconds%60);}
    @Override public void onUserInteraction(){super.onUserInteraction();lastInteraction=SystemClock.elapsedRealtime();}
    @Override public boolean dispatchKeyEvent(KeyEvent event){
        int key=event.getKeyCode();if(dismissKey==key){if(event.getAction()==KeyEvent.ACTION_UP)dismissKey=-1;return true;}
        if(saver!=null&&event.getAction()==KeyEvent.ACTION_DOWN&&(key==KeyEvent.KEYCODE_BACK||key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER||key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_DOWN||key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT||key==KeyEvent.KEYCODE_MENU)){dismissKey=key;stopSaver();return true;}
        if(key==KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE||key==KeyEvent.KEYCODE_MEDIA_NEXT||key==KeyEvent.KEYCODE_MEDIA_PREVIOUS){if(event.getAction()==KeyEvent.ACTION_DOWN&&event.getRepeatCount()==0)command(key==KeyEvent.KEYCODE_MEDIA_NEXT?"next":key==KeyEvent.KEYCODE_MEDIA_PREVIOUS?"previous":"toggle");return true;}return super.dispatchKeyEvent(event);
    }
    @Override public void onBackPressed(){if(saver!=null)stopSaver();else if(lyricsVisible)closeLyrics();else if(!"home".equals(tab)){artistQuery="";select("home");activeNav().requestFocus();}else super.onBackPressed();}
    @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus){lastInteraction=SystemClock.elapsedRealtime();if(root!=null&&root.findFocus()==null)activeNav().requestFocus();}}
    @android.annotation.SuppressLint("UnspecifiedRegisterReceiverFlag")
    @Override protected void onStart(){super.onStart();active=true;lastInteraction=SystemClock.elapsedRealtime();if(Build.VERSION.SDK_INT>=33)registerReceiver(changed,new IntentFilter(LauncherinPlayerService.CHANGED),Context.RECEIVER_NOT_EXPORTED);else registerReceiver(changed,new IntentFilter(LauncherinPlayerService.CHANGED));images.resume();main.post(tick);}
    @Override protected void onStop(){active=false;root.setKeepScreenOn(false);main.removeCallbacks(tick);++searchGeneration;++lyricsGeneration;if(searchJob!=null)searchJob.cancel(true);searchWorker.getQueue().clear();if(lyricJob!=null)lyricJob.cancel(true);busy=false;lyricsKey="";unregisterReceiver(changed);images.pause();super.onStop();}
    @Override protected void onDestroy(){closed=true;main.removeCallbacksAndMessages(null);images.close();searchWorker.shutdownNow();lyricWorker.shutdownNow();super.onDestroy();}
